# Simple modular affine tests: selected class(es) of a*r+b*c mod m
for m in range(2,13):
 for a in range(m):
  for b in range(m):
   classes={}
   for pts,_ in datasets:
    for r,c,y in pts:
     k=(a*r+b*c)%m
     classes.setdefault(k,set()).add(y)
   pure={k:next(iter(v)) for k,v in classes.items() if len(v)==1}
   if all(((a*r+b*c)%m in pure) and pure[(a*r+b*c)%m]==y for pts,_ in datasets for r,c,y in pts):
    print('fits residue partition',m,a,b,pure)
    raise SystemExit
